9287f7ca:  ;
 ;DGJTUDIS procedure to determine if a transcription record is delinquent
 ;based on its status and various date/time parameters.
 ;

830eb231: ; .;
 ;If status is 'INCOMPLETE', calculate days delinquent based on
 ;transcription date and time limit.
 ;If delinquent, call DAYS to calculate exact number of days delinquent.
 ;

7fd11e82: ; .;
 ;If status is 'DICTATED', set delinquent flag and call DAYS
 ;to calculate exact number of days delinquent.
 ;

34ccf893: ; .;
 ;If status is 'TRANSCRIBED', calculate days delinquent based on
 ;transcription date/time and time limit for verification.
 ;If delinquent, call DAYS to calculate exact number of days delinquent.
 ;

f7bc5aff:  .;
 ;If record has an authentication time, and status is 'SIGNED',
 ;calculate days delinquent based on authentication date/time
 ;and time limit for authentication.
 ;If delinquent, call DAYS to calculate exact number of days delinquent.
 ;
